<?php
declare(strict_types=1);
require_once __DIR__.'/config/config.php';
require_once __DIR__.'/includes/site.php';
$slug=trim((string)($_GET['slug']??''));
$project=null;
if($slug!==''){try{$s=db()->prepare('SELECT * FROM projects WHERE slug=? AND is_published=1 LIMIT 1');$s->execute([$slug]);$project=$s->fetch();}catch(Throwable $e){$project=null;}}
$esc=static fn($v):string=>htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');
$siteName=(string)setting('site_name',APP_NAME);
$baseUrl=rtrim((string)app_url(),'/');
$absoluteUrl=static function(string $path)use($baseUrl):string{if($path==='')return '';if(preg_match('#^https?://#i',$path))return $path;return $baseUrl.'/'.ltrim($path,'/');};
if(!$project){http_response_code(404);$title='Case Study Not Found';$meta='The requested case study could not be found.';$canonical=$baseUrl.'/case-study.php';$ogImage='';}
else{$title=(string)($project['meta_title']??'')?:((string)($project['title']??'Case Study').' | Case Study');$meta=(string)($project['meta_description']??'')?:((string)($project['short_description']??''));$canonical=$baseUrl.'/case-study.php?slug='.rawurlencode((string)$project['slug']);$ogImage=$absoluteUrl((string)($project['featured_image']??''));}
$gallery=[];
if($project&&!empty($project['gallery'])){$decoded=json_decode((string)$project['gallery'],true);if(is_array($decoded))foreach($decoded as $item){if(is_string($item)&&trim($item)!=='')$gallery[]=$item;}}
$techs=$project?preg_split('/[,|]+/',(string)($project['technologies']??'')):[];
$features=$project?preg_split('/\r\n|\r|\n/',(string)($project['key_features']??'')):[];
$heroImage=$project?$absoluteUrl((string)($project['featured_image']??'')):'';
$schema=$project?['@context'=>'https://schema.org','@type'=>'CreativeWork','name'=>(string)$project['title'],'description'=>$meta,'url'=>$canonical,'image'=>$heroImage?:null,'creator'=>['@type'=>'Organization','name'=>$siteName]]:null;
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="<?=$esc($meta)?>"><link rel="canonical" href="<?=$esc($canonical)?>"><meta property="og:type" content="website"><meta property="og:title" content="<?=$esc($title)?>"><meta property="og:description" content="<?=$esc($meta)?>"><meta property="og:url" content="<?=$esc($canonical)?>"><?php if($ogImage):?><meta property="og:image" content="<?=$esc($ogImage)?>"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:image" content="<?=$esc($ogImage)?>"><?php else:?><meta name="twitter:card" content="summary"><?php endif;?><meta name="twitter:title" content="<?=$esc($title)?>"><meta name="twitter:description" content="<?=$esc($meta)?>"><title><?=$esc($title)?><?php if($siteName):?> | <?=$esc($siteName)?><?php endif;?></title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css" rel="stylesheet"><link href="<?=htmlspecialchars(app_url('assets/css/style.css'))?>" rel="stylesheet"><?php if($schema):?><script type="application/ld+json"><?=json_encode(array_filter($schema,static fn($v)=>$v!==null),JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE)?></script><?php endif;?><style>.case-hero{padding:150px 0 90px;background:#07111f;color:#fff}.case-label{letter-spacing:.14em;text-transform:uppercase;font-size:.78rem;font-weight:800;color:#8ea4bd}.case-title{font-size:clamp(2.6rem,6vw,5rem);font-weight:800;line-height:1.02}.case-image{min-height:420px;border-radius:28px;background:#101d2d center/cover no-repeat;box-shadow:0 30px 80px rgba(0,0,0,.18)}.case-content{padding:90px 0}.case-content h2{font-weight:800;margin-bottom:18px}.case-content p{font-size:1.08rem;line-height:1.85;color:#536173}.case-meta{border-top:1px solid #dce2e8;border-bottom:1px solid #dce2e8;padding:28px 0;margin:35px 0}.case-meta strong{display:block;color:#101827}.case-meta span{color:#536173}.case-cta{background:#07111f;color:#fff;border-radius:28px;padding:55px}.tag{display:inline-block;background:#edf2f7;border-radius:999px;padding:7px 13px;margin:4px;font-size:.85rem}.gallery-img{width:100%;height:280px;object-fit:cover;border-radius:18px}.feature-list li{margin-bottom:12px;color:#536173}.result-box{background:#f4f7fa;border-radius:20px;padding:30px}</style></head><body><nav class="navbar navbar-expand-lg navbar-dark bg-dark"><div class="container py-2"><a class="navbar-brand fw-bold" href="<?=$esc(app_url())?>"><?=$esc($siteName)?></a><a href="<?=$esc(app_url('index.php#projects'))?>" class="btn btn-outline-light btn-sm ms-auto">Back to Portfolio</a></div></nav><?php if(!$project):?><main class="case-hero"><div class="container"><div class="case-label">404 — CASE STUDY</div><h1 class="case-title mt-3">Case study not found.</h1><p class="lead text-white-50 mt-4">The requested case study is unavailable.</p><a class="btn btn-light mt-3" href="<?=$esc(app_url('index.php#projects'))?>">View Projects</a></div></main><?php else:?><header class="case-hero"><div class="container"><div class="row align-items-center g-5"><div class="col-lg-7"><div class="case-label"><?=$esc($project['category']??'Project')?></div><h1 class="case-title mt-3"><?=$esc($project['title']??'')?></h1><p class="lead text-white-50 mt-4"><?=$esc($project['short_description']??'')?></p><div class="d-flex flex-wrap gap-2 mt-4"><?php if(!empty($project['live_url'])):?><a class="btn btn-light" href="<?=$esc($project['live_url'])?>" target="_blank" rel="noopener noreferrer">Visit Live Project <i class="bi bi-arrow-up-right"></i></a><?php endif;if(!empty($project['github_url'])):?><a class="btn btn-outline-light" href="<?=$esc($project['github_url'])?>" target="_blank" rel="noopener noreferrer">View Code <i class="bi bi-github"></i></a><?php endif;?></div></div><div class="col-lg-5"><div class="case-image"<?php if($heroImage):?> style="background-image:url('<?=$esc($heroImage)?>')"<?php endif;?>></div></div></div></div></header><main class="case-content"><div class="container"><div class="case-meta"><div class="row g-4"><div class="col-md-3"><strong>Client</strong><span><?=$esc($project['client_name']??'—')?></span></div><div class="col-md-3"><strong>Industry</strong><span><?=$esc($project['industry']??$project['category']??'—')?></span></div><div class="col-md-3"><strong>Project Type</strong><span><?=$esc($project['project_type']??'—')?></span></div><div class="col-md-3"><strong>Duration</strong><span><?=$esc($project['project_duration']??'—')?></span></div></div></div><div class="row g-5"><div class="col-lg-8"><section class="mb-5"><div class="case-label text-dark">01 — PROJECT SCOPE</div><h2>What we set out to build</h2><p><?=nl2br($esc($project['project_scope']?:$project['short_description']))?></p></section><section class="mb-5"><div class="case-label text-dark">02 — OBJECTIVES</div><h2>Business goals</h2><p><?=nl2br($esc($project['objectives']?:'Create a professional, usable and scalable digital experience aligned with the business goals.'))?></p></section><section class="mb-5"><div class="case-label text-dark">03 — THE CHALLENGE</div><h2>Where the project started</h2><p><?=nl2br($esc($project['challenge']?:$project['short_description']))?></p></section><section class="mb-5"><div class="case-label text-dark">04 — STRATEGY</div><h2>Our approach</h2><p><?=nl2br($esc($project['strategy']?:'We combined discovery, information architecture, responsive UX and maintainable development to create a focused solution.'))?></p></section><section class="mb-5"><div class="case-label text-dark">05 — THE SOLUTION</div><h2>What we delivered</h2><p><?=nl2br($esc($project['solution']?:'A responsive digital solution designed around the project requirements.'))?></p></section><?php if(array_filter($features)):?><section class="mb-5"><div class="case-label text-dark">06 — KEY FEATURES</div><h2>What makes the solution work</h2><ul class="feature-list"><?php foreach($features as $feature):if(trim($feature)):?><li><?=$esc(trim($feature))?></li><?php endif;endforeach;?></ul></section><?php endif;?><?php if(!empty($project['results'])):?><section class="mb-5"><div class="case-label text-dark">07 — RESULTS & OUTCOMES</div><h2>Impact</h2><div class="result-box"><p class="mb-0"><?=nl2br($esc($project['results']))?></p></div></section><?php endif;?></div><div class="col-lg-4"><div class="p-4 bg-light rounded-4 sticky-lg-top" style="top:100px"><div class="case-label text-dark">TECH STACK</div><div class="mt-3"><?php foreach($techs as $tech):if(trim($tech)):?><span class="tag"><?=$esc(trim($tech))?></span><?php endif;endforeach;?></div></div></div></div><?php if($gallery):?><section class="mt-5"><div class="case-label text-dark">08 — PROJECT GALLERY</div><h2>Inside the project</h2><div class="row g-4 mt-1"><?php foreach($gallery as $image):$imageUrl=$absoluteUrl($image);?><div class="col-md-6"><img src="<?=$esc($imageUrl)?>" class="gallery-img" alt="<?=$esc($project['title'])?> project screenshot" loading="lazy"></div><?php endforeach;?></div></section><?php endif;?><div class="case-cta mt-5"><div class="case-label">READY FOR YOUR NEXT PROJECT?</div><h2 class="display-6 fw-bold mt-2">Let's build something that moves your business forward.</h2><a href="<?=$esc(app_url('index.php#contact'))?>" class="btn btn-light mt-3">Start a Project <i class="bi bi-arrow-up-right"></i></a></div></div></main><?php endif;?><footer class="bg-dark text-white-50 py-4"><div class="container small">© <?=date('Y')?> <?=$esc($siteName)?></div></footer></body></html>